{"path": "app/api/handlers.py", "file_text": """"Request handlers."""

from app.services import users

_VALID_BY = ("name_length", "email_length")


def handle_get_user(params: dict) -> tuple[int, dict]:
    raw = params.get("id")
    if not isinstance(raw, str) or not raw.isdigit():
        return 400, {"error": "invalid id"}
    user = users.get_user(int(raw))
    if user is None:
        return 404, {"error": "not found"}
    return 200, user


def handle_top_users(params: dict) -> tuple[int, dict]:
    by = params.get("by")
    if by not in _VALID_BY:
        return 400, {"error": "invalid request"}

    raw = params.get("n")
    if not isinstance(raw, str) or not raw.isdigit():
        return 400, {"error": "invalid request"}
    n = int(raw)
    if not 1 <= n <= 10:
        return 400, {"error": "invalid request"}

    field = "name" if by == "name_length" else "email"
    ranked = sorted(users.list_users(), key=lambda user: (-len(user[field]), user["id"]))
    return 200, {"users": ranked[:n]}
"}

